    'np.steps.h2': 'What to Expect When You Come to AWAREmed',
    'np.step1.h3': 'Request Your Consultation',
    'np.step1.p': 'Fill out our <a href="contact.html#book">online consultation form</a>, call us at (423) 430-6170, or email us. We\'ll confirm your appointment and send any intake forms needed.',
    'np.step2.h3': 'Complete Your Intake',
    'np.step2.p': 'Before your visit, you\'ll complete a comprehensive health history form. The more detail you provide, the more productive your consultation will be.',
    'np.step3.h3': 'Your First Visit',
    'np.step3.p': 'Dr. Akoury meets with you in an unhurried consultation, listening to your full story, asking detailed questions, and conducting a thorough evaluation tailored to your concerns.',
    'np.prep.eyebrow': 'Preparation',
    'np.prep.h2': 'How to Prepare for Your Visit',
    'np.prep.c1.h3': 'Bring Your Medical Records',
    'np.prep.c1.p': 'Previous lab results, imaging reports, specialist notes, and a list of current medications and supplements are all helpful. The more context Dr. Akoury has, the more complete your evaluation will be.',
    'np.prep.c2.h3': 'Write Down Your Symptoms &amp; Goals',
    'np.prep.c2.p': 'Patients often find it helpful to write down their top concerns before the visit. What are you experiencing? What do you hope to achieve? What has conventional care not yet addressed?',
    'np.prep.c3.h3': 'Choose Your Preferred Language',
    'np.prep.c3.p': 'Let us know if you\'d prefer to consult in Arabic, French, or Spanish. Dr. Akoury speaks all four languages and wants you to feel entirely comfortable during your visit.',
    'np.prep.c4.h3': 'List All Supplements &amp; Medications',
    'np.prep.c4.p': 'Include everything, prescription medications, OTC drugs, vitamins, herbs, and supplements. This is essential for safe, comprehensive care.',
    'np.faq.eyebrow': 'FAQs for New Patients',
    'np.faq.h2': 'Common New Patient Questions',
    'np.faq1.q': 'Does AWAREmed replace my primary care physician?',
    'np.faq1.a': 'No. AWAREmed is designed to work alongside your existing medical team, not replace it. Dr. Akoury specializes in integrative and functional approaches that complement your conventional care.',
    'np.faq2.q': 'How long are consultations?',
    'np.faq2.a': 'Initial consultations at AWAREmed are comprehensive and typically last 60–90 minutes. This is intentional — Dr. Akoury believes that taking time to listen properly is essential to good medicine.',
    'np.faq3.q': 'Are virtual consultations available?',
    'np.faq3.a': 'Yes. Many services and follow-up consultations can be conducted virtually, making Dr. Akoury\'s care accessible to patients near and far. Let us know your preference when you book.',
    'np.faq4.q': 'What if I have complex or chronic health issues?',
    'np.faq4.a': 'Patients with complex, chronic health situations are often exactly who integrative medicine is best suited to help. Dr. Akoury takes time to understand your full history and takes a systematic, root-cause approach to even the most complex presentations.',
    'np.faq5.q': 'Do I need a referral?',
    'np.faq5.a': 'In most cases, no referral is needed to book a consultation with Dr. Akoury. Please contact us directly and we\'ll guide you through the process.',
    'np.cta.eyebrow': 'Ready?',
    'np.cta.h2': 'Book Your First Consultation Today',
    'np.cta.p': 'Begin your whole-person health journey with a personalized, unhurried consultation with Dr. Dalal Akoury, MD.',
    /* ── Contact page ── */
    'contact.hero.eyebrow': 'Get in Touch',
    'contact.hero.h1': 'Contact &amp; Book a Consultation',
    'contact.hero.lead': 'Ready to take the first step? We\'re here to help, in-person in Johnson City, TN and virtually worldwide. Fill out the form below and we\'ll be in touch shortly.',
