    'section.about.bio1': 'الدكتورة عكوري هي مؤسسة AWAREmed — طبيبة متكاملة تمتد خبرتها في الطب الوظيفي والتجديدي ومكافحة الشيخوخة والصحة الأيضية ودعم أورام متكامل.',
