    'np.hero.eyebrow': 'مرحبًا',
    'np.hero.h1': 'جديد في AWAREmed؟ أهلًا بك.',
    'np.hero.lead': 'يسعدنا وجودك. إليك كل ما تحتاج معرفته قبل زيارتك الأولى، حتى تصل محضرًا ومستنيرًا وواثقًا.',
    'np.steps.eyebrow': 'زيارتك الأولى',
    'np.steps.h2': 'ما تتوقعه عند قدومك إلى AWAREmed',
    'np.step1.h3': 'اطلب استشارتك',
    'np.step1.p': 'املأ <a href="contact.html#book">نموذج الاستشارة الإلكتروني</a>، أو اتصل بنا على (423) 430-6170، أو راسلنا. سنؤكد موعدك ونرسل أي نماذج تسجيل مطلوبة.',
    'np.step2.h3': 'أكمل نموذج التسجيل',
    'np.step2.p': 'قبل زيارتك، ستكمل نموذجًا شاملًا للتاريخ الصحي. كلما قدمت تفاصيل أكثر، كانت استشارتك أكثر إنتاجية.',
    'np.step3.h3': 'زيارتك الأولى',
    'np.step3.p': 'تلتقي بك د. عكوري في استشارة غير متسرعة، تستمع لقصتك الكاملة وتطرح أسئلة تفصيلية وتجري تقييمًا شاملًا.',
    'np.prep.eyebrow': 'التحضير',
    'np.prep.h2': 'كيف تستعد لزيارتك',
    'np.prep.c1.h3': 'أحضر سجلاتك الطبية',
    'np.prep.c1.p': 'نتائج المختبر السابقة وتقارير التصوير وملاحظات المتخصصين وقائمة الأدوية والمكملات الحالية كلها مفيدة.',
    'np.prep.c2.h3': 'سجّل أعراضك وأهدافك',
    'np.prep.c2.p': 'يجد المرضى أنه من المفيد تدوين مخاوفهم الرئيسية قبل الزيارة. ما الذي تعانيه؟ ما الذي تأمل تحقيقه؟',
    'np.prep.c3.h3': 'اختر لغتك المفضلة',
    'np.prep.c3.p': 'أخبرنا إذا كنت تفضل الاستشارة بالعربية أو الفرنسية أو الإسبانية. تتحدث د. عكوري بجميع اللغات الأربع.',
    'np.prep.c4.h3': 'أدرج جميع المكملات والأدوية',
    'np.prep.c4.p': 'أدرج كل شيء: الأدوية الموصوفة والأدوية المتاحة دون وصفة والفيتامينات والأعشاب والمكملات.',
    'np.faq.eyebrow': 'أسئلة المرضى الجدد',
    'np.faq.h2': 'أسئلة شائعة للمرضى الجدد',
    'np.faq1.q': 'هل تحل AWAREmed محل طبيب الرعاية الأولية؟',
    'np.faq1.a': 'لا. AWAREmed مصممة للعمل جانب فريقك الطبي الحالي، لا بديلاً عنه. تتخصص د. عكوري في المناهج التكاملية والوظيفية التي تكمل رعايتك التقليدية.',
    'np.faq2.q': 'كم تستغرق الاستشارات؟',
    'np.faq2.a': 'الاستشارات الأولية في AWAREmed شاملة وتستغرق عادةً 60–90 دقيقة. هذا مقصود — د. عكوري تؤمن أن الاستماع بشكل صحيح ضروري لممارسة الطب الجيد.',
    'np.faq3.q': 'هل الاستشارات الافتراضية متاحة؟',
    'np.faq3.a': 'نعم. يمكن إجراء كثير من الخدمات والاستشارات المتابعة افتراضيًا، مما يجعل رعاية د. عكوري متاحة للمرضى القريبين والبعيدين.',
    'np.faq4.q': 'ماذا لو كانت لدي مشكلات صحية معقدة أو مزمنة؟',
    'np.faq4.a': 'المرضى ذوو الحالات المزمنة المعقدة هم في الغالب من يستفيد أكثر من الطب التكاملي. تأخذ د. عكوري وقتًا لفهم تاريخك الكامل وتتبع نهجًا منهجيًا يعالج السبب الجذري.',
    'np.faq5.q': 'هل أحتاج إلى إحالة؟',
    'np.faq5.a': 'في معظم الحالات، لا تحتاج إلى إحالة لحجز استشارة مع د. عكوري. تواصل معنا مباشرة وسنرشدك خلال العملية.',
    'np.cta.eyebrow': 'مستعد؟',
    'np.cta.h2': 'احجز استشارتك الأولى اليوم',
    'np.cta.p': 'ابدأ رحلتك الصحية الشاملة مع استشارة شخصية وغير متسرعة مع د. دلال عكوري.',
