    'svc.shared.disclaimer': '<strong>إخلاء المسؤولية الطبية:</strong> خدمات AWAREmed داعمة بطبيعتها وغير مخصصة لتشخيص أي مرض أو علاجه أو شفائه أو الوقاية منه. تتباين النتائج الفردية. تُقدم جميع الرعاية تحت إشراف الطبيب.',
