    'svcpage.hero.eyebrow': 'Soins Complets',
    'svcpage.hero.h1': 'Nos Services',
    'svcpage.hero.lead': 'Huit domaines de spécialité en médecine intégrative et fonctionnelle, chacun personnalisé selon votre biologie, votre historique et vos objectifs de santé.',
    'svcpage.hdr.eyebrow': 'Ce Que Nous Offrons',
    'svcpage.hdr.h2': 'Des Soins Complets, Dispensés avec Réflexion',
    'svcpage.hdr.lead': 'Chaque service est construit autour de votre histoire de santé unique, et non d\'un protocole universel. Cliquez sur un service pour en savoir plus.',
    'svcpage.oncology.h3': 'Soutien en Oncologie Intégrative',
    'svcpage.oncology.p': 'Soins de soutien holistiques conçus pour compléter votre traitement conventionnel du cancer, traitant la fatigue, la nutrition, l\'immunité et la qualité de vie.',
    'svcpage.iv.h3': 'Thérapie IV &amp; Hydratation',
    'svcpage.iv.p': 'Thérapie intraveineuse aux nutriments et à l\'hydratation sous supervision médicale pour l\'énergie, l\'immunité, la récupération et le bien-être.',
    'svcpage.hormone.h3': 'Optimisation Hormonale (BHRT)',
    'svcpage.hormone.p': 'Une évaluation complète de votre écosystème hormonal avec une thérapie de remplacement hormonal bioidentique personnalisée pour restaurer l\'équilibre.',
    'svcpage.regen.h3': 'Médecine Régénérative',
    'svcpage.regen.p': 'Approches dirigées par des médecins soutenant la capacité naturelle de guérison de votre corps au niveau cellulaire.',
    'svcpage.chelation.h3': 'Soutien à la Chélation &amp; Détoxification',
    'svcpage.chelation.p': 'Chélation soigneusement surveillée sous supervision médicale et soutien complet à la détoxification traitant la charge en métaux lourds.',
    'svcpage.gut.h3': 'Santé Intestinale &amp; Médecine Fonctionnelle',
    'svcpage.gut.p': 'Médecine fonctionnelle traitant la cause profonde des déséquilibres du microbiome, des dysfonctions digestives et des sensibilités alimentaires.',
    'svcpage.brain.h3': 'Bien-Être Cérébral &amp; Cognitif',
    'svcpage.brain.p': 'Soutien holistique pour la clarté mentale, la mémoire, l\'humeur et la concentration, traitant les causes profondes de la dysfonction cognitive.',
    'svcpage.skin.h3': 'Peau &amp; Anti-Âge',
    'svcpage.skin.p': 'Une approche intégrative de l\'intérieur vers l\'extérieur pour la santé de la peau, traitant l\'équilibre hormonal, le statut nutritionnel et l\'inflammation.',
    'svcpage.learnmore': 'En savoir plus →',
    'svcpage.cta.eyebrow': 'Vous ne savez pas par où commencer ?',
    'svcpage.cta.h2': 'Trouvons Ensemble le Bon Chemin pour Vous',
    'svcpage.cta.p': 'Réservez une consultation avec le Dr Akoury et elle vous aidera à déterminer quels services correspondent le mieux à votre histoire de santé.',
    /* ── New Patient page ── */
    'np.hero.eyebrow': 'Bienvenue',
    'np.hero.h1': 'Nouveau patient chez AWAREmed ? Bienvenue.',
    'np.hero.lead': 'Nous sommes ravis de vous avoir trouvé. Voici tout ce que vous devez savoir avant votre première visite, pour que vous puissiez arriver préparé, informé et confiant.',
    'np.steps.eyebrow': 'Votre Première Visite',
    'np.steps.h2': 'À Quoi S\'Attendre Quand Vous Venez chez AWAREmed',
    'np.step1.h3': 'Demandez Votre Consultation',
    'np.step1.p': 'Remplissez notre <a href="contact.html#book">formulaire de consultation en ligne</a>, appelez-nous au (423) 430-6170, ou envoyez-nous un e-mail. Nous confirmerons votre rendez-vous et enverrons les formulaires nécessaires.',
    'np.step2.h3': 'Complétez Votre Dossier',
    'np.step2.p': 'Avant votre visite, vous compléterez un formulaire complet d\'historique de santé. Plus vous fournissez de détails, plus votre consultation sera productive.',
    'np.step3.h3': 'Votre Première Visite',
    'np.step3.p': 'Le Dr Akoury vous rencontre lors d\'une consultation non précipitée, écoutant toute votre histoire, posant des questions détaillées et conduisant une évaluation approfondie.',
    'np.prep.eyebrow': 'Préparation',
    'np.prep.h2': 'Comment Se Préparer pour Votre Visite',
    'np.prep.c1.h3': 'Apportez Vos Dossiers Médicaux',
    'np.prep.c1.p': 'Les résultats de laboratoire précédents, les rapports d\'imagerie, les notes de spécialistes et une liste de médicaments et suppléments actuels sont tous utiles.',
    'np.prep.c2.h3': 'Notez Vos Symptômes &amp; Objectifs',
    'np.prep.c2.p': 'Les patients trouvent souvent utile de noter leurs principales préoccupations avant la visite. Que ressentez-vous ? Qu\'espérez-vous accomplir ?',
    'np.prep.c3.h3': 'Choisissez Votre Langue Préférée',
    'np.prep.c3.p': 'Informez-nous si vous préférez consulter en arabe, français ou espagnol. Le Dr Akoury parle les quatre langues et veut que vous vous sentiez entièrement à l\'aise.',
    'np.prep.c4.h3': 'Listez Tous les Suppléments &amp; Médicaments',
    'np.prep.c4.p': 'Incluez tout : médicaments sur ordonnance, médicaments en vente libre, vitamines, herbes et suppléments. C\'est essentiel pour des soins complets et sécurisés.',
    'np.faq.eyebrow': 'FAQ pour les Nouveaux Patients',
    'np.faq.h2': 'Questions Courantes des Nouveaux Patients',
    'np.faq1.q': 'AWAREmed remplace-t-il mon médecin de soins primaires ?',
    'np.faq1.a': 'Non. AWAREmed est conçu pour travailler aux côtés de votre équipe médicale existante, sans la remplacer. Le Dr Akoury se spécialise dans les approches intégratives et fonctionnelles qui complètent vos soins conventionnels.',
    'np.faq2.q': 'Combien de temps durent les consultations ?',
    'np.faq2.a': 'Les consultations initiales chez AWAREmed sont complètes et durent généralement 60 à 90 minutes. C\'est intentionnel — le Dr Akoury croit que prendre le temps d\'écouter correctement est essentiel à la bonne médecine.',
    'np.faq3.q': 'Les consultations virtuelles sont-elles disponibles ?',
    'np.faq3.a': 'Oui. De nombreux services et consultations de suivi peuvent être effectués virtuellement, rendant les soins du Dr Akoury accessibles aux patients proches et lointains.',
    'np.faq4.q': 'Et si j\'ai des problèmes de santé complexes ou chroniques ?',
    'np.faq4.a': 'Les patients ayant des situations de santé complexes et chroniques sont souvent exactement ceux que la médecine intégrative est la mieux placée pour aider. Le Dr Akoury prend le temps de comprendre votre historique complet.',
    'np.faq5.q': 'Ai-je besoin d\'une référence ?',
    'np.faq5.a': 'Dans la plupart des cas, aucune référence n\'est nécessaire pour réserver une consultation avec le Dr Akoury. Contactez-nous directement et nous vous guiderons.',
    'np.cta.eyebrow': 'Prêt ?',
    'np.cta.h2': 'Réservez Votre Première Consultation Aujourd\'hui',
    'np.cta.p': 'Commencez votre parcours de santé holistique avec une consultation personnalisée et non précipitée avec le Dr Dalal Akoury, MD.',
    /* ── Contact page ── */
